SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.admission_type, a.admit_provider_id, a.admission_location, a.discharge_location, a.insurance, a.language, a.marital_status, a.race, a.edregtime, a.edouttime, a.hospital_expire_flag, i.icd_code, i.icd_version, s.stay_id, s.first_careunit, s.last_careunit, s.intime, s.outtime, s.los, p.dod, lag(p.dod) OVER (PARTITION BY p.subject_id ORDER BY a.admittime) AS previous_dod, lead(p.dod) OVER (PARTITION BY p.subject_id ORDER BY a.dischtime DESC) AS next_dod, dense_rank() OVER (PARTITION BY p.gender, p.anchor_year_group ORDER BY a.admittime) AS admission_rank, count(DISTINCT e.itemid) OVER (PARTITION BY p.subject_id, s.stay_id, e.charttime) AS medication_count, percent_rank() OVER (PARTITION BY p.gender, p.anchor_year_group ORDER BY a.admittime) AS admission_percentile, row_number() OVER (PARTITION BY p.subject_id, s.stay_id ORDER BY a.admittime) AS admission_row_number, lag(s.intime) OVER (PARTITION BY p.subject_id ORDER BY s.stay_id) AS previous_stay_intime, lead(s.outtime) OVER (PARTITION BY p.subject_id ORDER BY s.stay_id DESC) AS next_stay_outtime, dense_rank() OVER (PARTITION BY p.gender, p.anchor_year_group ORDER BY s.stay_id) AS stay_rank, count(DISTINCT r.itemid) OVER (PARTITION BY p.subject_id, r.chartdate) AS reimbursement_count, percent_rank() OVER (PARTITION BY p.gender, p.anchor_year_group ORDER BY s.stay_id) AS stay_percentile, row_number() OVER (PARTITION BY p.subject_id, s.stay_id ORDER BY s.stay_id) AS stay_row_number FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.stay_id = s.stay_id JOIN diagnoses_icd i ON a.subject_id = i.subject_id AND a.hadm_id = i.hadm_id JOIN reimbursements r ON a.subject_id = r.subject_id AND a.hadm_id = r.hadm_id AND r.chartdate BETWEEN a.admittime AND a.dischtime WHERE p.gender = 'M' AND p.anchor_age BETWEEN 89 AND 99 AND i.icd_code = '887.0' AND i.icd_version = '4' AND s.intime BETWEEN a.admittime AND a.dischtime AND s.outtime BETWEEN s.intime AND a.dischtime;